const sources = [
  ['Qwen', 'Qwen'],
  ['google', 'gemma'],
  ['nvidia', 'Nemotron'],
  ['openai', 'gpt-oss'],
  ['mistralai', 'Mistral'],
  ['zai-org', 'GLM'],
  ['deepseek-ai', 'DeepSeek'],
  ['moonshotai', 'Kimi'],
  ['microsoft', 'Phi'],
  ['meta-llama', 'Llama'],
  ['CohereLabs', 'command']
];

return sources.map(([author, search]) => ({
  json: {
    author,
    search,
    url: `https://huggingface.co/api/models?author=${encodeURIComponent(author)}&search=${encodeURIComponent(search)}&sort=createdAt&direction=-1&limit=100&full=true`
  }
}));

const BASELINE = {
  id: 'Qwen/Qwen3.6-35B-A3B',
  released: '2026-04-16T00:00:00.000Z',
  totalB: 35,
  activeB: 3,
  quant: 'UD-Q4_K_M',
  weightGB: 22.13,
  contextK: 32
};

const PRECREATION_GRACE_MS = 45 * 24 * 60 * 60 * 1000;

const raw = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const byId = new Map(raw.filter(model => model && model.id).map(model => [model.id, model]));

function parameterCounts(id) {
  const name = id.split('/').pop();
  const activeMatch = name.match(/(?:^|[-_])A(\d+(?:\.\d+)?)([BT])(?:[-_]|$)/i);
  const sizeMatches = [...name.matchAll(/(?:^|[-_])(\d+(?:\.\d+)?)([BT])(?=[-_]|$)/gi)];
  const convert = match => match ? Number(match[1]) * (match[2].toUpperCase() === 'T' ? 1000 : 1) : null;
  return {
    totalB: sizeMatches.length ? convert(sizeMatches[sizeMatches.length - 1]) : null,
    activeB: convert(activeMatch)
  };
}

function qwenGeneration(id) {
  const match = id.match(/Qwen3(?:\.(\d+))?/i);
  return match ? Number(`3.${match[1] || 0}`) : null;
}

function releaseKind(model) {
  const name = model.id.toLowerCase();
  const tags = (model.tags || []).map(String);
  const derived = tags.some(tag => tag.startsWith('base_model:quantized:'));
  if (derived || /(?:^|[-_])(base|fp8|awq|gptq|gguf|nvfp4|mxfp)(?:[-_]|$)/i.test(name)) return 'derived';
  if (/embedding|rerank|guard|reward|asr|tts|forcedalign|ocr|drive/.test(name)) return 'specialist';
  if (!['text-generation', 'image-text-to-text'].includes(model.pipeline_tag)) return 'other-task';
  if (!tags.includes('conversational')) return 'not-chat';
  return 'candidate';
}

function assess(model) {
  const counts = parameterCounts(model.id);
  const tags = (model.tags || []).map(String);
  const created = model.lastModified || model.createdAt;
  const isMoe = counts.activeB !== null || tags.some(tag => /moe/i.test(tag));
  const estimatedQ4GB = counts.totalB === null ? null : Math.round(counts.totalB * 0.63 * 10) / 10;
  let fit = 'size needs verification';
  if (estimatedQ4GB !== null) {
    fit = estimatedQ4GB <= 42 ? 'comfortable' : estimatedQ4GB <= 50 ? 'tight' : 'does not fit safely';
  }
  const sameFamilyGeneration = qwenGeneration(model.id);
  const newerQwen = sameFamilyGeneration !== null && sameFamilyGeneration > 3.6;
  const evalResults = tags.includes('eval-results');
  let evidence = 0;
  if (new Date(created) > new Date(BASELINE.released)) evidence += 1;
  if (evalResults) evidence += 1;
  if (newerQwen) evidence += 2;
  if (counts.totalB !== null && counts.totalB >= 20) evidence += 1;
  if (isMoe && counts.activeB !== null && counts.activeB <= 10) evidence += 1;
  if (fit === 'does not fit safely') evidence -= 3;

  let verdict = 'watch';
  if (fit === 'does not fit safely') verdict = 'reject: memory';
  else if (newerQwen && evidence >= 4) verdict = 'likely quality upgrade';
  else if (evidence >= 4) verdict = 'benchmark contender';

  const reasons = [];
  reasons.push(isMoe ? `MoE${counts.activeB ? `, ~${counts.activeB}B active` : ''}` : 'dense or unconfirmed architecture');
  reasons.push(estimatedQ4GB === null ? 'quantized size unknown' : `estimated Q4 weights ~${estimatedQ4GB} GB`);
  if (newerQwen) reasons.push('newer Qwen generation than baseline');
  if (evalResults) reasons.push('publisher attached evaluation results');
  if (!isMoe) reasons.push('expect slower generation than the A3B baseline');

  return {
    id: model.id,
    created,
    url: `https://huggingface.co/${model.id}`,
    architecture: isMoe ? 'MoE' : 'dense/unknown',
    totalB: counts.totalB,
    activeB: counts.activeB,
    estimatedQ4GB,
    fit,
    verdict,
    evidence,
    reasons
  };
}

const candidates = [...byId.values()]
  .filter(model => releaseKind(model) === 'candidate')
  .filter(model => model.id !== BASELINE.id)
  .filter(model => {
    const generation = qwenGeneration(model.id);
    return generation === null || generation > 3.6;
  })
  .filter(model => {
    const baselineTime = new Date(BASELINE.released).getTime();
    const createdTime = new Date(model.createdAt || model.lastModified).getTime();
    const updatedTime = new Date(model.lastModified || model.createdAt).getTime();
    return createdTime > baselineTime || (updatedTime > baselineTime && createdTime >= baselineTime - PRECREATION_GRACE_MS);
  })
  .map(assess)
  .filter(candidate => ['comfortable', 'tight'].includes(candidate.fit))
  .filter(candidate => candidate.evidence >= 4)
  .sort((a, b) => b.evidence - a.evidence || new Date(b.created) - new Date(a.created));

const state = $getWorkflowStaticData('global');
const previouslySeen = new Set(state.seenCandidateIds || []);
const newCandidates = candidates.filter(candidate => !previouslySeen.has(candidate.id));
state.seenCandidateIds = candidates.map(candidate => candidate.id);
state.lastSuccessfulScan = new Date().toISOString();
state.baseline = BASELINE.id;

const lines = [
  '# Weekly local-model upgrade check',
  '',
  `Checked: ${new Date().toISOString()}`,
  `Baseline: ${BASELINE.id} (${BASELINE.quant}, ${BASELINE.weightGB} GB, ${BASELINE.contextK}K configured context)`,
  'Machine constraint: MacBook M1 Max, 64 GB unified memory; target <=42 GB Q4 weights, 42–50 GB is tight.',
  '',
  'A “likely upgrade” is evidence for testing, not proof. Benchmark settings differ between publishers.',
  ''
];

if (!candidates.length) {
  lines.push('No credible, Mac-compatible upgrade candidates found.');
} else {
  lines.push('| Candidate | Verdict | Architecture | Fit | Published/updated |', '|---|---|---|---|---|');
  for (const c of candidates) {
    lines.push(`| [${c.id}](${c.url}) | ${c.verdict} | ${c.architecture}${c.activeB ? ` A${c.activeB}B` : ''} | ${c.fit}${c.estimatedQ4GB ? ` (~${c.estimatedQ4GB} GB Q4)` : ''} | ${String(c.created).slice(0, 10)} |`);
  }
  lines.push('', 'Before switching: confirm a supported GGUF/MLX build, compare identical prompts, measure tokens/s, and review Danish/English interview-analysis output.');
}

return [{ json: {
  checkedAt: new Date().toISOString(),
  baseline: BASELINE,
  candidateCount: candidates.length,
  newCandidateCount: newCandidates.length,
  shouldNotify: newCandidates.length > 0,
  newCandidates,
  candidates,
  markdown: lines.join('\n')
} }];
